#include <stdio.h>

int main() {
  int num = 10;          // An integer variable
  int *ptr;              // A pointer to an integer

  ptr = &num;            // Assign the address of 'num' to 'ptr'

  printf("Value of num: %d\n", num);          // Accessing num directly
  printf("Address of num: %p\n", &num);        // Accessing num's address
  printf("Value of ptr: %p\n", ptr);          // Accessing ptr's value (address)
  printf("Value pointed to by ptr: %d\n", *ptr); // Dereferencing ptr to access num's value

  *ptr = 20;            // Modifying the value at the address stored in ptr
  printf("New value of num: %d\n", num);       // Showing the changed value of num
  return 0;
}
